  font-size: 0.875rem;
  opacity: 0.7;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: white;
  padding: 1.5rem;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  z-index: 200;
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.cookie-text {
  flex: 1;
}

.cookie-text h4 {
  font-size: 0.9375rem;
  margin-bottom: 0.25rem;
}

.cookie-text p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.cookie-actions {
  display: flex;
  gap: 0.75rem;
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 1.5rem;
  transition: transform 0.4s ease;
}

.carousel-item {
  flex: 0 0 calc(33.333% - 1rem);
  min-width: 280px;
}

.carousel-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.5rem;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: white;
  border: 2px solid var(--primary);
  color: var(--primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--primary);
  color: white;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0.5rem;
  border-bottom: 2px solid #E5E7EB;
  margin-bottom: 2rem;
  overflow-x: auto;
}

.tab-btn {
  padding: 1rem 1.5rem;
  background: none;
  border: none;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  position: relative;
  white-space: nowrap;
  transition: color 0.2s;
}

.tab-btn::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--primary);
  transform: scaleX(0);
  transition: transform 0.2s;
}

.tab-btn:hover {
  color: var(--text-dark);
}

.tab-btn.active {
  color: var(--primary);
}

.tab-btn.active::after {
  transform: scaleX(1);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Form Elements */
.form-group {
  margin-bottom: 1rem;
}

.form-label {
  display: block;
  font-weight: 500;
  margin-bottom: 0.5rem;
  font-size: 0.875rem;
}

.form-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 2px solid #E5E7EB;
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: border-color 0.2s;
}

.form-input:focus {
  outline: none;
  border-color: var(--primary);
}

/* Search Box */
.search-box {
  position: relative;
}

.search-box .form-input {
  padding-left: 3rem;
}

.search-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}

/* Toggle */
.toggle-group {
  display: inline-flex;
  background: #E5E7EB;
  border-radius: var(--radius-lg);
  padding: 0.25rem;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  background: none;
  border: none;
  border-radius: var(--radius-md);
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.toggle-btn.active {
  background: white;
  box-shadow: var(--shadow-sm);
  color: var(--primary);
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--warm-cream);
  color: var(--coffee-brown);
  border-radius: var(--radius-lg);
  font-size: 0.75rem;
  font-weight: 600;
}

/* Image Placeholder */
.img-placeholder {
  background: linear-gradient(135deg, #d1d5db 0%, #e5e7eb 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .featured-inner {
    grid-template-columns: 1fr;
    text-align: center;
  }
}

@media (max-width: 768px) {
  .nav-main {
    display: none;
  }

  .nav-toggle {
    display: block;
  }

  .grid-2, .grid-3 {
    grid-template-columns: 1fr;
  }

  .hero {
    padding: 3rem 1.5rem;
  }

  .section {
    padding: 3rem 1.5rem;
  }

  .seasonal-grid {
    grid-template-columns: 1fr;
  }

  .promo-section {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cookie-inner {
    flex-direction: column;
    text-align: center;
  }

  .grid-4 {
    grid-template-columns: 1fr;
  }

  .carousel-item {
    flex: 0 0 calc(100% - 1rem);
  }
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background: white;
  z-index: 150;
  padding: 1.5rem;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.mobile-nav-links a {
  font-size: 1.25rem;
  font-weight: 500;
  padding: 0.75rem 0;
  border-bottom: 1px solid #E5E7EB;
}

