    function slideCarousel(trackId, direction) {
      const track = document.getElementById(trackId);
      const items = track.querySelectorAll('.carousel-item, .category-carousel-item');
      const itemWidth = items[0].offsetWidth + 24; // include gap
      const currentTransform = parseInt(track.style.transform.replace('translateX(', '').replace('px)', '')) || 0;
      const maxTranslate = 0;
      const minTranslate = -((items.length - Math.floor(track.parentElement.offsetWidth / itemWidth)) * itemWidth);
      let newTransform = currentTransform - (direction * itemWidth);

      newTransform = Math.max(minTranslate, Math.min(maxTranslate, newTransform));
      track.style.transform = 'translateX(' + newTransform + 'px)';
    }

    function toggleFaq(button) {
      const faqItem = button.parentElement;
      faqItem.classList.toggle('open');
