  <script>
    function toggleMobileNav() {
      document.getElementById('mobileNav').classList.toggle('open');
    }

    function toggleFilter() {
      const panel = document.getElementById('filterPanel');
      const btn = document.getElementById('filterBtn');
      panel.classList.toggle('show');
      btn.classList.toggle('active');
    }

    function toggleFilterChip(chip) {
      chip.classList.toggle('active');
    }

    function setOrderType(type) {
      const btns = document.querySelectorAll('.order-type-btn');
      btns.forEach(btn => btn.classList.remove('active'));
      event.target.classList.add('active');
    }

    function selectStore(card) {
      document.querySelectorAll('.store-card').forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
    }

    function handleSearch() {
      const input = document.getElementById('searchInput');
      const suggestions = document.getElementById('suggestions');

      if (input.value.length > 0) {
        // Mock suggestions based on input
        const mockSuggestions = [
          { name: 'Downtown San Francisco', address: 'San Francisco, CA' },
          { name: 'Market Street', address: '450 Market St, San Francisco, CA' },
          { name: 'Union Square', address: '201 Powell St, San Francisco, CA' },
          { name: 'Financial District', address: '88 California St, San Francisco, CA' },
          { name: 'SOMA', address: '600 Mission St, San Francisco, CA' }
        ].filter(s => s.name.toLowerCase().includes(input.value.toLowerCase()) ||
                      s.address.toLowerCase().includes(input.value.toLowerCase()));

        if (mockSuggestions.length > 0) {
          suggestions.innerHTML = mockSuggestions.map(s => `
            <div class="suggestion-item" onclick="selectSuggestion('${s.name}')">
              <strong>${s.name}</strong>
              <span>${s.address}</span>
            </div>
          `).join('');
          suggestions.classList.add('show');
        } else {
          suggestions.classList.remove('show');
        }
      } else {
        suggestions.classList.remove('show');
      }
    }

    function selectSuggestion(name) {
      document.getElementById('searchInput').value = name;
      document.getElementById('suggestions').classList.remove('show');
    }

    // Close suggestions when clicking outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-box')) {
        document.getElementById('suggestions').classList.remove('show');
      }
    });
  </script>
